```swift
func find(_ app: XCUIApplication, _ label: String) -> XCUIElement {
    if let _ = Optional(app.buttons[label]), app.buttons[label].exists { return app.buttons[label] }
    let pred = NSPredicate(format: "label == %@ OR identifier == %@ OR title == %@", label, label, label)
    return app.descendants(matching: .any).matching(pred).firstMatch
}
```

