Test source:

import XCTest

final class RunnerUITests: XCTestCase {
    func testDrive() throws {
        let app = XCUIApplication(bundleIdentifier: "im.vector.app")
        app.activate()
        _ = app.waitForExistence(timeout: 10)
        let env = ProcessInfo.processInfo.environment
        var log = ""
        func note(_ s: String) { log += s + "\n" }
        func dump() {
            let d = app.debugDescription
            try? d.write(toFile: "/tmp/uidump.txt", atomically: true, encoding: .utf8)
            note("dumped")
        }
        if let cmds = env["CMDS"] {
            for cmd in cmds.components(separatedBy: "|") {
                let parts = cmd.components(separatedBy: ":")
                guard let op = parts.first else { continue }
                switch op {
                case "tap":
                    let label = parts.dropFirst().joined(separator: ":")
                    var el = app.buttons[label]
                    if !el.exists {
                        let pred = NSPredicate(format: "label == %@ OR identifier == %@", label, label)
                        el = app.descendants(matching: .any).matching(pred).firstMatch
                    }
                    if el.waitForExistence(timeout: 5) {
                        el.tap()
                        note("tapped \(label)")
                    } else {
                        note("MISS \(label)")
                    }
                case "sleep":
                    let t = parts.count > 1 ? (Double(parts[1]) ?? 1) : 1
                    Thread.sleep(forTimeInterval: t)
                    note("slept \(t)")
                case "dump":
                    dump()
                default:
                    note("unknown \(op)")
                }
                Thread.sleep(forTimeInterval: 0.7)
            }
        } else {
            if !app.waitForExistence(timeout: 10) { note("app not found") }
            dump()
        }
        try? log.write(toFile: "/tmp/uilog.txt", atomically: true, encoding: .utf8)
    }
}

Note: the test must not fail; ensure no XCTAssert that could fail.

